const ICON = { dev_started: '🤖', dev_done: '📬', qa_started: '🛡️', qa_accepted: '🟢', qa_rejected: '🔴', merged: '🔀', merge_failed: '⚠️', blocked: '🛑', image_pushed: '📦', deployed: '🚀', deploy_failed: '💥' };
const repo = 'https://github.com/Arvingrep/firebird-sea';
return $input.all().map(({ json }) => {
  const e = json.body || json;
  const lines = [`${ICON[e.stage] || 'ℹ️'} <b>${e.stage || 'event'}</b>`, (e.message || '').replace(/[<>&]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;' }[c]))];
  if (e.issue) lines.push(`Issue: <a href="${repo}/issues/${e.issue}">#${e.issue}</a>`);
  if (e.pr) lines.push(`PR: <a href="${repo}/pull/${e.pr}">#${e.pr}</a>`);
  if (e.site) lines.push(`站点: ${e.site}`);
  if (e.image) lines.push(`镜像: <code>${String(e.image).split(':').pop().slice(0, 12)}</code>`);
  if (e.run_url) lines.push(`<a href="${e.run_url}">运行日志</a>`);
  return { json: { text: lines.join('\n') } };
});
